$(document).ready(function() {
    $('.actionBtn').on('click',function () {
        var action = $(this).data('action');
        $("#actionForm").find('input[name="action"]').val(action);
        $('#actionFormModalLabel').html(action);
        if (action == 'paid') {
            $('#paymentinfoLabel').html("payment code");
        } else {
            $('#paymentinfoLabel').html(action + ' information');
        }
        $('#actionFormModal').modal('show');
    });
    $('.btn-action-submit').on('click',function () {
        $("#actionForm").submit();
    });
});